-- id: B-95
-- title: VS: οι γέφυρες v5 δεν είναι ίσες με τις στάσεις εθνικής πλευράς
-- flows: F-10,F-23
-- severity: P1
-- schedule: hourly
-- red: > 0
-- baseline:
-- queue: no
-- entity: orders
-- impact: Μια στάση εθνικής πλευράς VS στο v5 χωρίς γέφυρα δεν εμφανίζεται ΠΡΟΣ ΑΝΑΘΕΣΗ στο Εβδομαδιαίο Εθνικών (κανείς δεν την προγραμματίζει)· μια γέφυρα σε στάση που δεν το θέλει κρατά φορτίο σε φορτηγό χωρίς λόγο.
-- next: Owner + εθνικών: η VS στο Εβδομαδιαίο Εθνικών και τα plan_notices της. Συνήθως εκτελεσμένο σκέλος που η 074 δεν έσβησε σκόπιμα (vs_changed_after_execution): απόφαση ανθρώπου.
-- exceptions: Ο κανόνας του spec 8 και της 074 (plan_h_bridge_wanted), ξαναγραμμένος εδώ χωρίς συναρτήσεις του TMS (ο ελεγκτής δεν τις καλεί): ζωντανή VS, όχι Cancelled, ημέρα κόμβου ≥ L ή «μια φορά v5, πάντα v5», στάση ζωντανή με παλέτες στην εθνική πλευρά (εισαγωγή Unloading, εξαγωγή Loading). Ελέγχει και το via_hub. Πριν από το L: 0.
-- tolerance:
-- source: DRAFT 074b (plan F5 Task C, spec 8) · PGlite 28/10: 0 on the production copy, red in the scenario of plan-074.test.mjs
-- enabled: yes
SELECT count(*) FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM 'Cancelled' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = 'Import' AND s.stop_type = 'Unloading') OR (o.direction = 'Export' AND s.stop_type = 'Loading'), false) AND (coalesce(o.cross_dock_date >= (SELECT c.cutover_day FROM plan_config c), false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM '074 rollback'))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL) OR s.via_hub <> (o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM 'Cancelled' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = 'Import' AND s.stop_type = 'Unloading') OR (o.direction = 'Export' AND s.stop_type = 'Loading'), false) AND (coalesce(o.cross_dock_date >= (SELECT c.cutover_day FROM plan_config c), false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM '074 rollback')))));
-- @ids
SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM (SELECT coalesce(o.legacy_id, o.id::text) AS x FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM 'Cancelled' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = 'Import' AND s.stop_type = 'Unloading') OR (o.direction = 'Export' AND s.stop_type = 'Loading'), false) AND (coalesce(o.cross_dock_date >= (SELECT c.cutover_day FROM plan_config c), false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM '074 rollback'))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL) OR s.via_hub <> (o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM 'Cancelled' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND coalesce((o.direction = 'Import' AND s.stop_type = 'Unloading') OR (o.direction = 'Export' AND s.stop_type = 'Loading'), false) AND (coalesce(o.cross_dock_date >= (SELECT c.cutover_day FROM plan_config c), false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM '074 rollback'))))) ORDER BY 1 LIMIT 50) s;
